"""Bounded local regex gate using independently stopped and reaped workers."""
import hashlib,json,re,threading,time
from pathlib import Path
import subprocess

APPROVED_PATTERN=r'^(?:ERROR|WARN):'

class RuleGate:
    def __init__(self,rules,limits,spawn,audit_path):
        if not isinstance(rules,dict) or not 1<=len(rules)<=8:raise ValueError('rules')
        for name,pattern in rules.items():
            if not isinstance(name,str) or not re.fullmatch('[a-z][a-z0-9_]{0,15}',name):raise ValueError('approved non-sensitive identifier required')
            if type(pattern)is not str or not 1<=len(pattern)<=256 or len(pattern.encode('utf8'))>256:raise ValueError('pattern bytes')
        bounds={'workers':(1,4),'waiting':(0,4),'queue_ms':(10,500),'exec_ms':(50,1000),'max_input_bytes':(1,4096)}
        if not isinstance(limits,dict) or set(limits)!=set(bounds):raise ValueError('limits')
        if any(type(limits[key])is not int or not low<=limits[key]<=high for key,(low,high) in bounds.items()):raise ValueError('limits')
        self.rules=dict(rules);self.limits=dict(limits);self.spawn=spawn
        self.condition=threading.Condition();self.active=0;self.waiting=0;self.disabled=set();self.calls=0;self.closed=False;self.audit_failed=False
        self.audit=Path(audit_path).open('x',encoding='utf8',newline='')

    def _record(self,rule_id,status,mode,size,entered,**details):
        event={'rule_id':rule_id,'status':status,'mode':mode,'input_bytes':size,
               'disabled':rule_id in self.disabled,'elapsed_ms':round((time.monotonic()-entered)*1000,3),
               'pid':None,'exit_code':None,'reaped':False,'started_matching':False,'rule_sha256':None,'matched':None}
        event.update(details)
        try:self.audit.write(json.dumps(event,sort_keys=True)+'\n');self.audit.flush()
        except OSError:
            self.audit_failed=True
            raise RuntimeError('audit unavailable')from None
        return event

    def match(self,rule_id,text):
        entered=time.monotonic()  # Queue deadline includes validation and condition-lock delay.
        with self.condition:
            if self.closed or self.audit_failed:raise RuntimeError('closed or audit unavailable')
        if type(rule_id)is not str or len(rule_id)>16 or rule_id not in self.rules or type(text)is not str:raise ValueError('request')
        if len(text)>self.limits['max_input_bytes']:raise ValueError('input byte budget')
        try:size=len(text.encode('utf8'))
        except UnicodeEncodeError as error:raise ValueError('input encoding')from error
        if size>self.limits['max_input_bytes']:raise ValueError('input byte budget')
        admission_deadline=entered+self.limits['queue_ms']/1000
        queued=False
        with self.condition:
            if self.closed or self.audit_failed:raise RuntimeError('closed or audit unavailable')
            self.calls+=1
            if self.calls>16:raise ValueError('finite exercise call budget')
            while True:
                if self.audit_failed:
                    if queued:self.waiting-=1
                    raise RuntimeError('audit unavailable')
                if time.monotonic()>=admission_deadline:
                    if queued:self.waiting-=1
                    return self._record(rule_id,'queue_timeout','none',size,entered)
                if self.active<self.limits['workers']:
                    if queued:self.waiting-=1
                    self.active+=1
                    mode='approved' if rule_id in self.disabled else 'custom'
                    pattern=APPROVED_PATTERN if mode=='approved' else self.rules[rule_id]
                    execution_deadline=time.monotonic()+self.limits['exec_ms']/1000
                    break
                if not queued:
                    if self.waiting>=self.limits['waiting']:
                        return self._record(rule_id,'overload','none',size,entered)
                    self.waiting+=1;queued=True
                self.condition.wait(max(0,admission_deadline-time.monotonic()))
        deadline=execution_deadline
        process=None;status='worker_error';matched=None;output=b''
        try:
            process=self.spawn()
            payload=json.dumps({'pattern':pattern,'text':text},ensure_ascii=False).encode('utf8')
            remaining=max(0,deadline-time.monotonic())
            try:output,errors=process.communicate(input=payload,timeout=remaining)
            except subprocess.TimeoutExpired:
                process.terminate();output,errors=process.communicate(timeout=1)
                status='timeout'
            else:
                if process.returncode==0:
                    rows=[json.loads(line) for line in output.decode('utf8').splitlines()]
                    result=rows[-1]
                    if result.get('phase')!='result' or result.get('pid')!=process.pid:raise ValueError('worker protocol')
                    if result['status']=='compile_error':status='compile_error'
                    elif result['status']=='ok' and type(result.get('matched'))is bool:
                        matched=result['matched'];status='match' if matched else 'no_match'
        except (OSError,ValueError,KeyError,TypeError):
            status='worker_error'
        finally:
            if process is not None and process.poll()is None:
                process.terminate();output,_=process.communicate(timeout=1)
            with self.condition:
                if mode=='custom' and status in ('timeout','compile_error','worker_error'):self.disabled.add(rule_id)
                self.active-=1
                try:
                    rows=[json.loads(line) for line in output.decode('utf8').splitlines()]
                    started=any(row.get('phase')=='matching' and row.get('pid')==process.pid for row in rows) if process is not None else False
                except (ValueError,UnicodeError):started=False
                try:
                    event=self._record(rule_id,status,mode,size,entered,
                        pid=process.pid if process else None,exit_code=process.returncode if process else None,
                        reaped=process is not None and process.returncode is not None,started_matching=started,
                        rule_sha256=hashlib.sha256(pattern.encode('utf8')).hexdigest(),matched=matched)
                finally:self.condition.notify_all()
        return event

    def close(self):
        with self.condition:
            if self.active or self.waiting:raise RuntimeError('finish all calls before close')
            self.closed=True;self.audit.close()
